INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_role_account', 'exec_secretary', 'Create the ward''s role account', 'role-account', 'Make one shared Google account for the calling, not for a person, so everything you build passes to the next Executive Secretary.', replace('## What this gives the ward\n\nOne Google account that belongs to the calling, not to you. The calendars, booking pages, short links, Zoom and trackers you set up in the next steps all live on it, so when you are released the next Executive Secretary gets everything by receiving one password.\n\nYou and the other leaders still sign in to WardForward with your own Google accounts. The role account is for the shared tools.\n\n## Steps\n\n- **1.** On a computer, go to [accounts.google.com/signup](https://accounts.google.com/signup) and create a new, free Google account.\n- **2.** Name it for the calling, not for yourself. For example, first name "Ward" and last name "Bishopric", with an address like yourwardnamebishopric@gmail.com. Pick something the next bishopric will recognize.\n- **3.** Choose a long password. Agree with the bishop where it will be kept (for example, written down and kept by the bishop, or in a password manager he can also open).\n- **4.** Turn on 2-Step Verification: go to [myaccount.google.com](https://myaccount.google.com), open Security, then 2-Step Verification, and follow the prompts. Use your own phone for the codes for now.\n- **5.** Still under Security, set the recovery phone and recovery email. Use your phone and the bishop''s email, so that the account can be recovered even if you are unavailable.\n- **6.** Open Google Calendar on this account once and check its time zone (Settings, then Time zone). It must be your ward''s time zone.\n- **7.** Right away, ask for zippa.run access from this account (see the note below).\n\n## Done when\n\n- A shared Google account exists for the calling, not for a person.\n- 2-Step Verification is on.\n- The recovery phone and recovery email are set, and the bishop knows how the next Executive Secretary takes them over.\n- The bishop knows where the password is kept.\n- The zippa.run access request has been sent from this account.\n\n## Notes\n\n**Send the zippa.run access request now.** zippa.run is the short-link service your ward will use for its QR codes (step 7). Each request is approved by hand, so it can take a few days. Go to [app.zippa.run](https://app.zippa.run), choose Sign in with Google, pick the role account, and fill in the form with your name, an email you read and a phone number. Step 7 picks up from there once you are approved.\n\nWhen you hand the calling on, you give the next Executive Secretary the password, and they replace the 2-Step Verification phone and recovery details with their own (step 14 covers the hand-off).\n\nNever use the role account for anything personal, and never keep member records in it.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 1) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_wardforward_setup', 'exec_secretary', 'Set up WardForward: callings and spaces', 'wardforward-setup', 'Request your ward, invite the bishopric and ward council with their callings, and give each organization''s leaders their space.', replace('## What this gives the ward\n\nEvery leader signs in to WardForward with their own Google account and sees what belongs to their calling. Each organization gets its own space (Elders Quorum, Relief Society, Primary and so on), and the Bishopric and Ward Council spaces hold what those councils share. Doing this early lets the bishopric help with the later steps.\n\n## Before you start\n\nThe bishop must approve the ward using WardForward (General Handbook 38.8.21.2). Ask him first.\n\n## Steps\n\n- **1.** Sign in at [app.wardforward.com](https://app.wardforward.com) with your own Google account (not the role account).\n- **2.** Click Request a workspace. Fill in Ward name, Unit number and Your calling, tick "Our bishop has approved using WardForward for our ward", and click Submit request. A WardForward operator approves each new ward. If your ward is already on WardForward, your request goes to that ward''s admins instead.\n- **3.** Once approved, open your ward. You are its first Superadmin (WardForward''s word for a ward administrator).\n- **4.** Under "Invite a leader (callings chart)", invite the bishop: his Email, Calling "Bishop", Ward role "Superadmin", Space "Bishopric", Space role "Owner". Click Create / update invite. He gets an email with a link to accept; the same link shows under "Pending invites".\n- **5.** Invite the counselors and the Ward Clerk to the Bishopric space the same way, with Ward role "Member".\n- **6.** Invite each organization''s president and secretary to their own organization''s space with Space role "Owner". The owners of a space manage it.\n- **7.** Add the ward council members to the Ward Council space too. To put someone in a second space, submit the invite form again with the same email and the other space; it adds another space.\n- **8.** Under "Members & roles", check that both the bishop and you show "superadmin". If not, click Make superadmin.\n\n## Done when\n\n- The bishop approved the ward using WardForward (General Handbook 38.8.21.2).\n- The bishop and the Executive Secretary are both Superadmins, so the ward has at least two administrators.\n- The bishopric and the ward council are invited with their callings.\n- Each organization''s president and secretary are Owners of their organization''s space.\n- The Ward Clerk is in the Bishopric space.\n\n## Notes\n\n**Keep at least two administrators.** WardForward will not let the last Superadmin step down, but the ward should always have two: the bishop and the Executive Secretary.\n\n**Activities and missionary work.** An Activities committee chair or a Ward Mission Leader who is not in the Ward Council space sees only their own organization''s service posts. Add them to the Ward Council space if they should see the others.\n\n**Spaces you don''t use.** Every ward gets the same list of spaces. Ignore the ones your ward doesn''t use; there is no screen yet to hide or rename them.\n\n**Leaders who change callings.** WardForward has no screen yet to remove someone from a space. Invite the new leader into the same space, and tell the operator if a released leader should lose access now.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 2) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_google_plan', 'exec_secretary', 'Put the role account on the right Google plan', 'google-plan', 'Move the role account to a paid Google plan that allows several booking pages and checks more than one calendar.', replace('## What this gives the ward\n\nMembers will book their own interviews on Google Calendar booking pages (Google calls them appointment schedules). A free Google account can make only a basic booking page that checks one calendar. The interview setup in steps 4 to 6 needs two things a free account can''t do: several booking pages, and a page that checks more than one calendar before it offers a time. One paid plan on the role account covers the whole bishopric.\n\n## Steps\n\n- **1.** Ask the bishop how the ward will pay for the plan before you buy it.\n- **2.** On a computer, sign in to [one.google.com](https://one.google.com) as the role account.\n- **3.** Compare the plans and pick one that includes premium appointment scheduling (booking pages). Google renames its plans from time to time; the plan''s feature list should mention appointment schedules or booking pages. Wards using this setup have found the Google AI Plus plan enough.\n- **4.** Subscribe on the role account, not on your own account.\n- **5.** Check that it worked: in Google Calendar (as the role account), click Create, then Appointment schedule, and look for "Calendars checked for availability". On a paid plan you can add a second calendar there. You don''t need to save anything yet.\n\n## Done when\n\n- The role account is on a paid plan that allows several booking pages.\n- A booking page on the role account can check more than one calendar for availability.\n\n## Notes\n\n**Use a computer.** The booking-page settings you need, especially adding a second calendar to check, are only in Google Calendar on a desktop web browser. The phone app can''t do it. This is the most common reason people get stuck.\n\n**Write it down.** Record the plan, when it renews and who pays for it in the hand-off note (step 14), so it doesn''t lapse when you are released.\n\nIf you ever downgrade the account, the extra booking pages stop working, and members will see fewer open times than you expect.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 3) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_leader_calendars', 'exec_secretary', 'Create one calendar per leader', 'leader-calendars', 'Give the bishop and each counselor an interview calendar on the role account, named for the calling, and share it with them.', replace('## What this gives the ward\n\nEvery interview lands on the right leader''s own calendar, so each leader''s open times are independent: a member booking the 1st Counselor doesn''t take that time away from the 2nd Counselor or the bishop. Each leader sees their own interviews on their phone.\n\n## How it works\n\nGoogle always saves a booking to the role account''s own calendar first. You can''t change that. So the account''s own calendar becomes a temporary "staging" area that stays empty, each leader gets a calendar of their own, and the interview router (step 6) moves each new booking onto the right leader''s calendar within a minute.\n\n## Steps\n\n- **1.** On a computer, sign in to Google Calendar as the role account.\n- **2.** In the left column, find "Other calendars", click the + next to it, and choose "Create new calendar".\n- **3.** Create one calendar per leader, named for the calling, not the person: "Bishop Interviews", "1st Counselor Interviews" and "2nd Counselor Interviews". Click Create calendar for each.\n- **4.** Share each calendar with its leader: hover over the calendar in the left column, click the three dots, then "Settings and sharing". Under "Share with specific people or groups", add the leader''s own email and choose "See all event details".\n- **5.** Give each calendar its own color (the three dots again), so bookings are easy to tell apart.\n- **6.** Leave the account''s own calendar (it shows the account''s name) alone. Don''t add anything to it; it is the staging calendar.\n\n## Done when\n\n- There is one interview calendar per leader, the bishop included.\n- Each calendar is shared with its leader.\n- The account''s own calendar is left empty.\n\n## Notes\n\n**Why the bishop gets his own calendar too.** If the bishop used the account''s own calendar, his bookings would block the counselors. With his own calendar, his times can overlap theirs.\n\n**Why calling names.** When a counselor is released, nothing needs renaming: you only change who the calendar is shared with (step 14 lists this).\n\n**Keep the staging calendar visible on the role account.** If you untick the account''s own calendar in the left column, the "Booking pages" list disappears from the sidebar too. Nothing is deleted; tick it again and they come back. Leaders looking at their own calendars can hide it safely.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 4) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_booking_pages', 'exec_secretary', 'Create the booking pages', 'booking-pages', 'Make an appointment booking page for every kind of interview, each titled with its leader''s calling tag and checking that leader''s calendar.', replace('## What this gives the ward\n\nA web page for each kind of interview where a member picks an open time on their own: settings apart, temple recommends, time with the bishop, tithing declarations. Members stop waiting on phone calls and texts, and each leader''s calendar fills itself.\n\n## The one rule\n\nEvery booking page''s title must contain its leader''s calling tag, exactly, in square brackets: [Bishop], [1st Counselor] or [2nd Counselor]. The interview router (step 6) reads that tag to know whose calendar the booking belongs on. Use the same tag on every page for that leader.\n\n## Steps (repeat for each page)\n\n- **1.** On a computer, in Google Calendar as the role account, click Create, then Appointment schedule.\n- **2.** Title: the kind of interview, then the tag. For example "Settings Apart [1st Counselor]". Keep it short; long titles get cut off.\n- **3.** Appointment duration: 10 minutes for settings apart and tithing declarations, 20 minutes for temple recommends; the bishop''s own pages are 15, 20 and 30 minutes.\n- **4.** General availability: when that leader holds interviews, for example Sundays 12:00 to 1:00 PM.\n- **5.** Scheduling window: for example up to 60 days ahead. Minimum notice: for example 2 hours before. Buffer: none.\n- **6.** Under "Calendars checked for availability", add that leader''s calendar (for example "1st Counselor Interviews"). The account''s own calendar is already checked and can''t be unchecked; leave it.\n- **7.** Booking form: ask for the member''s name. Email is optional.\n- **8.** Description: "Please select the earliest time slot that aligns with your availability." followed by where the offices are in your building. Asking for the earliest slot keeps appointments packed together.\n- **9.** Untick "Add Google Meet video conferencing" (Meet doesn''t work with this setup; step 11 explains Zoom instead).\n- **10.** Save, open the booking page, and copy its calendar.app.google link. Keep a list of every page''s link; you need them in steps 7 and 8.\n\n## A typical set of pages\n\n- Settings Apart [1st Counselor] and Settings Apart [2nd Counselor], 10 minutes.\n- Temple Recommends [1st Counselor] and Temple Recommends [2nd Counselor], 20 minutes.\n- Interview 15 min [Bishop], Interview 20 min [Bishop] (also for first-time temple recommends) and Interview 30 min [Bishop].\n- Tithing Declaration [Bishop], 10 minutes. Tithing declarations are with the bishop only.\n\n## Done when\n\n- Every kind of appointment has a booking page whose title contains its leader''s calling tag in square brackets.\n- Each page checks that leader''s calendar as well as the account''s own.\n- You have a list of every page''s calendar.app.google link.\n\n## Notes\n\n**Times look an hour off?** A booking page shows times in the viewer''s time zone (top right of the page). Check that the role account''s time zone is your ward''s.\n\n**When a leader is released,** don''t make new pages: the tag is the calling, so the pages, their links and every QR code stay the same. Change the page''s description if it names the leader.\n\nBooking pages collect members'' names. Treat that list with the same care as any ward record.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 5) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_interview_router', 'exec_secretary', 'Install the interview router', 'interview-router', 'Install the small script that moves each new booking onto the right leader''s calendar every minute.', replace('## What this gives the ward\n\nEach new booking moves from the account''s staging calendar onto its leader''s calendar within a minute, and its title is tidied to something like "(1) Jane Doe (Settings Apart)". Each leader''s open times stay independent, and a member can still cancel from their confirmation email.\n\n## How it works\n\nThe interview router is a short Google Apps Script that runs on the role account every minute. It reads each new booking''s title, finds the calling tag ([Bishop], [1st Counselor] or [2nd Counselor]), and moves the booking onto that leader''s calendar. Then it marks the role account''s own place on the booking as "declined". That stops the booking from blocking the other leaders'' pages, while the member''s cancel link keeps working. (Removing the account from the booking instead would break the cancel link, so the script declines and never removes.)\n\n## Steps\n\n- **1.** Click "Use template" on this page to open the router script, select all of it and copy it.\n- **2.** Signed in as the role account, go to [script.google.com](https://script.google.com) and click New project. Delete the sample code, paste the router, and rename the project "Interview Router".\n- **3.** In the left sidebar, click the + next to Services, choose "Google Calendar API" and click Add.\n- **4.** Find each leader''s Calendar ID: in Google Calendar, open the calendar''s "Settings and sharing", scroll to "Integrate calendar", and copy the Calendar ID.\n- **5.** At the top of the script, in ROUTES, replace each PASTE_..._CALENDAR_ID_HERE with the matching Calendar ID. Keep the quote marks. Click Save.\n- **6.** In the function list at the top, choose checkCalendarIds and click Run. Google asks you to allow the script to use the account''s calendar: allow it (if it warns that the app isn''t verified, click Advanced, then go to Interview Router; it is your own script). In the log you want one OK line per leader. A BAD line means a Calendar ID to fix.\n- **7.** Click Triggers (the clock icon), then Add Trigger: function routeAppointments, event source "Time-driven", type "Minutes timer", "Every minute". Save.\n- **8.** Test it: book a time on a counselor''s page and on one of the bishop''s pages. Within a minute each should move to that leader''s calendar with a tidy title; the other leaders'' pages should still show that time open; and cancelling from the confirmation email should remove it. Then delete the test bookings.\n\n## Done when\n\n- The router runs every minute (its trigger is set).\n- checkCalendarIds shows every leader OK.\n- A test booking moves to the right leader''s calendar and can still be cancelled from the confirmation email.\n\n## Notes\n\n**A booking stays on the staging calendar?** Its page title doesn''t contain a tag the script knows. Check the square brackets and spelling in the title.\n\n**Why not Zapier or similar tools?** They can only copy a booking, which breaks the member''s cancel link, and their free plans only check every 15 minutes. The script moves the booking itself and costs nothing.\n\n**Occasional failure emails** from Google about "server error" are rare: the script retries Google''s hiccups and waits for the next minute. A failure email that keeps coming means something to fix.\n\n**When a leader is released,** the script needs no change: its tags are callings, and the calendar IDs stay the same.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 6) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_zippa_links', 'exec_secretary', 'Get zippa.run access and make your links', 'zippa-links', 'Make the role account a zippa.run creator on the ward''s prefix and make one short link per destination.', replace('## What this gives the ward\n\nShort, friendly web addresses like zippa.run/abcBulletin that send people on to the real page. Every QR code WardForward prints uses the short link, so when a destination changes you change it once on zippa.run, and every printed flyer keeps working.\n\n## How zippa.run works\n\nzippa.run is a separate service. Anyone can ask to join; an operator approves each request and ties the account to your ward''s prefix, a few letters that start every link your ward makes (in these examples, "abc"). Once approved, the role account can make any link that starts with the prefix. A name that doesn''t start with it, such as a link for the stake website, is a separate request the operator approves.\n\nWardForward can''t make zippa.run links for you. You make them on zippa.run and paste them into WardForward (steps 8 and 9).\n\n## Steps\n\n- **1.** If you haven''t yet, send the access request from the role account (step 1): [app.zippa.run](https://app.zippa.run), Sign in with Google, role account, then fill in the form. Wait for approval. Ask for the same prefix your ward uses on WardForward (it shows on your ward''s home page as "Public portal: /p/your-prefix").\n- **2.** Once approved, sign in to [app.zippa.run](https://app.zippa.run) as the role account.\n- **3.** Make one short link per destination. Start every name with your prefix and make the rest guessable. Point each one at its real address.\n- **4.** Write each short link down next to where it points. You''ll paste them into WardForward in the next steps.\n\n## Link name ideas\n\n- abcBulletin: the ward bulletin.\n- abcWelcome: the new-member form.\n- abcDiscord: the ward''s chat invite.\n- abcBishop, abcSetApart, abcTemple, abcTithe: the booking pages from step 5.\n- abcLinks: the ward''s public portal (step 8 tells you its address).\n- abcServe and abcHelp: the service pages (step 9).\n\n## Done when\n\n- The role account is a zippa.run creator on the ward''s prefix.\n- There is one short link for each destination you''ll share.\n\n## Notes\n\n**Names are permanent.** Once a short link name is taken it can never be used again, by anyone. Choose names carefully. What you can always change is where a link points.\n\n**Never delete a printed link.** If a page moves, point the old short link at the new place. Several short links may point at the same page.\n\n**The links belong to the calling.** Because the role account makes them, the next Executive Secretary keeps them all.\n\nIf your request is declined you can''t apply again from the same account; contact the zippa.run operator instead.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 7) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_public_portal', 'exec_secretary', 'Publish the ward''s public portal', 'public-portal', 'Put each ward link on WardForward''s public portal with its short link and QR code, and set the portal''s own share link.', replace('## What this gives the ward\n\nOne public page with every link members need (bulletin, forms, chat, interview booking pages), each with a QR code, plus one big QR code for the whole page. Members bookmark one address; you can change any link without reprinting anything.\n\n## Steps\n\n- **1.** On this page, set the status to In progress and click Save status. A Deliverables section appears below it.\n- **2.** Under "Add a link", fill in the Title members will see (for example "Ward Bulletin"), the real address (URL), and the short link you made in step 7 (for example zippa.run/abcBulletin). Click "Add link + generate QR".\n- **3.** In the new link''s card, choose "Public" in the list and click Publish. (The list starts on Bishopric; make sure it says Public.)\n- **4.** Repeat for each link, including each interview booking page.\n- **5.** Go back to your ward''s home page and open the Public portal (the "/p/your-prefix" link) to see it as members will.\n- **6.** On the ward home page under Portals, open "Public". Under "Portal sections", add a section such as "Interviews" with Add section, then under "Which section each link is in" move the booking pages into it with Move. Links you don''t move show under "Links".\n- **7.** Make a zippa.run short link (for example abcLinks) that points at the portal address shown under "Share link (optional)". Paste it there and click Save share link.\n\n## Done when\n\n- Each link is a deliverable published to Public with its short link pasted.\n- The portal''s share link is set.\n\n## Notes\n\n**Changing a link later.** Change where the short link points on zippa.run. The portal, its QR codes and every printed flyer keep working. If you forgot to add a short link, use "Save short link" on the link''s card.\n\n**The portal is public.** Anyone with the address can see it (search engines are asked not to list it). Never put members'' personal information or private documents on it. WardForward shows its independence notice at the bottom of every page for you.\n\n**You don''t need to build a website.** Some wards built their own links site before WardForward; WardForward''s portal replaces that. The WardForward demo site at [github.com/wardforward](https://github.com/wardforward) is only an example a ward may copy if it wants one.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 8) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_service_sections', 'exec_secretary', 'Turn on service opportunities and requests', 'service-sections', 'Turn on the portal''s Service Opportunities and Service Requests sections with their short links, and check who owns each service category.', replace('## What this gives the ward\n\nTwo sections at the top of the public portal. "Service Opportunities" lists the ways members can help right now (meals, moves, cleaning the building and more) and lets them sign up. "Service Requests" lets a member ask for help, privately, and the right leaders are told. Each section has its own short link and QR code, so you can also share it on its own.\n\n## Steps\n\n- **1.** On your ward''s home page, find "Portal service sections". Under each field it shows a "Direct address" (ending in /serve/your-prefix and /help/your-prefix).\n- **2.** On zippa.run, make two short links pointing at those two direct addresses, for example zippa.run/abcServe and zippa.run/abcHelp (with your own prefix in place of "abc").\n- **3.** Back in "Portal service sections", paste them into "Service Opportunities link" and "Service Requests link". Tick both "Show ... on the portal" boxes and click Save.\n- **4.** Open "Service opportunities & requests" from the ward home page. Under "Categories you manage", open each category. The line under its name says who owns it (for example "owned by Relief Society").\n- **5.** For each category, check that the owning space has its leaders as Owners (step 2). The owners of that space manage the category and get its messages.\n- **6.** Optional: under "Coordinators" (for opportunities) or "People who help with these requests" (for requests), pick a ward member and click Add, or invite someone by email. Coordinators run that category''s opportunities for its owners.\n- **7.** Optional: to announce new opportunities in a Discord channel, open the category''s "Discord channel" section and paste the channel''s webhook link (in Discord: Server Settings, Integrations, Webhooks), then Save.\n\n## The categories every ward starts with\n\n- Opportunities: Provide a Meal (Relief Society), Lend a Helping Hand (Ward Council), Help with an Activity (Activities Committee), Clean the Building (Bishopric), Clean the Temple (Relief Society and Elders Quorum), Substitute in Primary (Primary), Substitute in Sunday School (Sunday School), Help Someone Move (Elders Quorum).\n- Requests: Get Help Moving (Elders Quorum), Request a Christmas or Presents (Bishopric, confidential), Other Requests (Bishopric, confidential).\n\n## Done when\n\n- Both service sections are on.\n- Each section has its zippa.run short link pasted in "Portal service sections".\n- Each default category''s owning space has its leaders as Owners.\n- Optional: coordinators named, and a Discord channel webhook pasted where an organization wants one.\n\n## Notes\n\n**Confidential requests.** Christmas and Other requests are seen only by the bishopric space''s owners, the people named on the category and superadmins. The emails leaders get say a request came in, never what it says.\n\n**Keep the webhook private.** A Discord webhook link lets anyone post to that channel. WardForward never shows it in full once saved.\n\nRequests are deleted 30 days after they are closed.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 9) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_foyer_flyer', 'exec_secretary', 'Print the foyer flyer', 'foyer-flyer', 'Print a poster of the public portal, with a QR code for every link, and post it in the building.', replace('## What this gives the ward\n\nA printed page or poster in the foyer, on the bulletin board or in the bishop''s waiting area, with a QR code for each link and one big QR code for the whole portal. Members scan it with their phone camera. Because every code uses a short link, the flyer never needs reprinting when a link changes.\n\n## Steps\n\n- **1.** Do steps 7 to 9 first, so every link has its short link and the portal has its share link. The big QR code uses the share link.\n- **2.** On the ward home page, under Portals, open "Public", and click "print" at the top (next to "ward home"). It opens a Letter-size flyer in a new tab.\n- **3.** For a bigger size, add one of these to the end of that page''s address and press Enter: ?size=tabloid (11 by 17 inches), ?size=a4, ?size=poster-18x24 or ?size=poster-24x36.\n- **4.** Print it from the browser (Ctrl+P, or Cmd+P on a Mac). Choose "Save as PDF" if a print shop will print the poster. If colors are missing, turn on "Background graphics" in the print settings.\n- **5.** Scan every QR code on the printout with a phone before you post it.\n- **6.** Post it where members wait, with the bishop''s approval of where it goes.\n\n## Done when\n\n- A flyer or poster is printed from the portal''s print view.\n- Its QR codes were tested with a phone.\n- It is posted in the building.\n\n## Notes\n\n**Changing a link later** happens on zippa.run only. Reprint only when you add or remove links.\n\n**Hand-outs.** The Letter-size flyer also works as a hand-out for new members and new move-ins.\n\nKeep a PDF of the current flyer in the role account''s Drive and note it in the hand-off note (step 14).', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 10) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_zoom', 'exec_secretary', 'Set up virtual interviews (Zoom)', 'zoom', 'Set up a free Zoom account on the role account for the occasional interview held online, with recording and AI features turned off.', replace('## What this gives the ward\n\nWhen a member needs to meet online, the leader and the member each click one link and are in the meeting together, with nobody stuck waiting to be let in. Recording, transcripts and AI features are off for every meeting.\n\n## Why not Google Meet\n\nA Google Meet link''s host is always the event''s organizer, which is the role account. The role account never joins as a live person, so nobody can let the member in, and the leader can''t either. Zoom can make meetings that anyone with the link can join, with no host needed.\n\n## One-time setup\n\n- **1.** Go to [zoom.us](https://zoom.us), choose Sign in with Google, and pick the role account. There''s no separate Zoom password to hand on. The free plan is enough (meetings up to 40 minutes).\n- **2.** In Zoom''s Settings, turn Waiting Room off and "Join before host" on. Together these let anyone with the link join.\n- **3.** Still in Settings, turn these off: Recording ("Record to computer files" and "Automatic recording"), meeting transcripts, "Allow participants to transcribe meetings with My Notes", the AI Companion features, "Enable Screenshot feature in meeting chat", and under Zoom Apps "Share realtime meeting content with apps".\n- **4.** In the Chrome browser, install the Zoom Chrome Extension from the Chrome Web Store and sign in to it as the role account. It adds a "Make it a Zoom Meeting" button inside Google Calendar. (Don''t use the "Zoom for Google Workspace" add-on; it fails to sign in on free accounts.)\n- **5.** In Google Calendar, open each booking page and make sure "Add Google Meet video conferencing" is unticked.\n\n## Each time someone wants to meet online\n\n- **1.** In Chrome, open the member''s booking in Google Calendar and click Edit (the pencil).\n- **2.** Click "Make it a Zoom Meeting", then Save. The member gets the updated invitation with the link.\n- **3.** At the time, the leader and the member both click the link.\n\n## Done when\n\n- Zoom is set up on the role account.\n- Meetings are open-join (Waiting Room off, "Join before host" on).\n- Recording, transcripts and AI features are off.\n\n## Notes\n\n**Never keep interview details.** Don''t record, transcribe or write up what is said in an interview, in Zoom, in WardForward or anywhere else. Follow the General Handbook (38.8.32) on keeping such matters confidential. WardForward never stores interview content.\n\n**Be honest about the limit.** No video service can stop someone recording their own screen or pointing a phone at it. These settings remove the easy, built-in ways; the rest is the same trust an in-person interview relies on.\n\nScreen sharing, chat and the whiteboard are not a privacy risk; leave them on if leaders find them useful. Zoom changes its settings from time to time, so test a meeting once before you rely on it.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 11) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_bishopric_rotation', 'exec_secretary', 'Bishopric meeting assignment rotation', 'bishopric-rotation', 'Set up the tracker that suggests who gives each prayer and thought in bishopric meeting.', replace('## Done when\n\n- The tracker is copied from the template.\n- It is deployed as a web app.\n- Its link is a deliverable in the Bishopric space.\n\nFull how-to coming soon.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 12) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_council_rotation', 'exec_secretary', 'Ward Council assignment rotation', 'council-rotation', 'Set up the tracker that suggests who gives each prayer and thought in ward council.', replace('## Done when\n\n- The tracker is copied from the template.\n- It is deployed as a web app.\n- Its link is a deliverable in the Ward Council space.\n\nFull how-to coming soon.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 13) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_handoff_note', 'exec_secretary', 'Write the hand-off note', 'handoff-note', 'Leave a note in the role account''s Drive listing every account and tool, where it lives, and what to change when a leader is released.', replace('## What this gives the ward\n\nCallings change every few years. Because everything lives on the role account, a new Executive Secretary can take it all over in an afternoon, as long as someone wrote down what exists and where. This note is that list.\n\n## Steps\n\n- **1.** Signed in as the role account, open [drive.google.com](https://drive.google.com), click New, then Google Docs, and name it "Hand-off note: ward tools".\n- **2.** List every account and tool, using the outline below. For each one write what it is, where it lives (its address), and who can change it.\n- **3.** Write down where the role account''s password is kept, never the password itself.\n- **4.** Add the "When a leader is released" and "When the Executive Secretary is released" checklists below.\n- **5.** Share the note with the bishop. Update it whenever you change something.\n\n## What to list\n\n- The role account: its address, who keeps the password, and who holds the 2-Step Verification phone and recovery details.\n- The Google plan: which plan, when it renews and who pays.\n- The calendars: the account''s own (staging) calendar and each leader''s interview calendar, and who each is shared with.\n- The booking pages: each page''s title and link.\n- The interview router: the "Interview Router" project at script.google.com and its every-minute trigger.\n- zippa.run: the ward''s prefix and the list of short links and where each points.\n- WardForward: the ward''s administrators, the public portal''s address and share link, and the service section links.\n- The foyer flyer: where the current PDF is and where it''s posted.\n- Zoom: that it''s on the role account, and the privacy settings.\n- The assignment rotation trackers (steps 12 and 13): each one''s Sheet, web app link and where its PIN is kept.\n\n## When a leader is released\n\n- Re-share that leader''s interview calendar with the new leader''s email and remove the old share. Booking pages, the router and the short links don''t change, because they use the calling, not the name.\n- Change any booking-page description that names the leader.\n- In WardForward, invite the new leader with the same calling and spaces. Tell the operator if the released leader should lose access now.\n- Update the leader lists in the assignment rotation trackers.\n\n## When the Executive Secretary is released\n\n- Give the new Executive Secretary the password (or where it''s kept).\n- They sign in, set up their own 2-Step Verification, and replace the recovery phone and email with theirs.\n- The bishop makes the new Executive Secretary a Superadmin in WardForward.\n- Walk through this note together.\n\n## Done when\n\n- A note in the role account''s Drive lists every account and tool and where each lives.\n- It says what to change when a leader is released and when the Executive Secretary is released.\n- The bishop can open it.\n\n## Notes\n\nKeep the note to tools and accounts. Never put member information, interview details or the password itself in it.', '\n', char(10)), NULL, NULL, NULL, 'ward_singleton', 'published', 14) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
